export const CURRICULUM_SUBJECTS = {"schema":"pedagogy.curriculum-subjects.v1","purpose":"Reference data mapping each curriculum system (present in schools.json) to its stream/subject structure at Grade 9-12 level, so the expo app can conditionally show/hide questions and course-interest options based on a visitor's declared curriculum + stream + subjects (e.g. a PCMB/Science student should not be shown Commerce-only questions).","researched":"2026-09-19","curricula":{"Indian":{"label":"Indian / CBSE (and equivalent Indian boards)","structure":"stream-based","note":"Students pick ONE stream after Grade 10, then subjects within it. Streams are mutually exclusive in practice (a Science student does not also take Commerce papers), so the app should treat stream as the primary filter and subjects as a refinement within it.","streams":[{"id":"science-pcm","label":"Science (PCM)","core_subjects":["Physics","Chemistry","Mathematics"],"common_electives":["Computer Science","Physical Education","English"],"typical_course_interest":["Engineering","Technology / Computer Science","Architecture","Pure Sciences"],"excludes":["commerce-only content","humanities-only content"]},{"id":"science-pcb","label":"Science (PCB)","core_subjects":["Physics","Chemistry","Biology"],"common_electives":["Biotechnology","Psychology","English"],"typical_course_interest":["Medicine","Dentistry","Pharmacy","Life Sciences / Biotechnology","Nursing / Allied Health"],"excludes":["commerce-only content","humanities-only content"]},{"id":"science-pcmb","label":"Science (PCMB - both Maths and Biology)","core_subjects":["Physics","Chemistry","Mathematics","Biology"],"common_electives":["English"],"typical_course_interest":["Medicine","Engineering","Life Sciences","Pure Sciences"],"excludes":["commerce-only content","humanities-only content"]},{"id":"commerce-with-maths","label":"Commerce (with Mathematics)","core_subjects":["Accountancy","Business Studies","Economics","Mathematics / Applied Mathematics"],"common_electives":["Informatics Practices","Entrepreneurship","English"],"typical_course_interest":["Business / Management","Finance / Accounting","Economics","Data Science / Analytics"],"excludes":["science-only content (Physics/Chemistry/core Biology)"]},{"id":"commerce-without-maths","label":"Commerce (without Mathematics)","core_subjects":["Accountancy","Business Studies","Economics"],"common_electives":["Informatics Practices","Entrepreneurship","English"],"typical_course_interest":["Business / Management","Finance / Accounting","Economics","Hospitality / Retail Management"],"excludes":["science-only content"]},{"id":"humanities","label":"Humanities / Arts","core_subjects":["History","Political Science","Geography","Economics"],"common_electives":["Psychology","Sociology","Fine Arts","Physical Education","English"],"typical_course_interest":["Law","Media / Journalism / Communication","Psychology","Social Sciences","Design / Fine Arts","Hospitality / Tourism"],"excludes":["science-only content"]}]},"IB":{"label":"IB Diploma Programme (IBDP)","structure":"six-subject-groups","note":"Students pick ONE subject from each of the 6 groups (3 at Higher Level, 3 at Standard Level) plus the DP core (TOK, Extended Essay, CAS). No hard exclusions between groups, but the group-4/group-5 choices signal STEM leaning and group-3/group-6 choices signal humanities/arts leaning.","groups":[{"id":"group1","label":"Studies in Language & Literature","subjects":["Language A: Literature","Language A: Language and Literature","Literature and Performance"]},{"id":"group2","label":"Language Acquisition","subjects":["Classical Languages","Language Ab Initio","Language B"]},{"id":"group3","label":"Individuals & Societies","subjects":["Business Management","Digital Society","Economics","Geography","Global Politics","History","Philosophy","Psychology","Social & Cultural Anthropology","World Religions"],"typical_course_interest":["Business / Management","Economics","Law","Social Sciences","Psychology"]},{"id":"group4","label":"Sciences","subjects":["Biology","Chemistry","Computer Science","Design Technology","Environmental Systems & Societies","Physics","Sports Exercise & Health Science"],"typical_course_interest":["Medicine","Engineering","Technology / Computer Science","Life Sciences","Environmental Science"]},{"id":"group5","label":"Mathematics","subjects":["Analysis & Approaches","Applications & Interpretation"]},{"id":"group6","label":"The Arts","subjects":["Dance","Film","Music","Theatre","Visual Arts"],"typical_course_interest":["Design / Fine Arts","Media / Journalism / Communication"]}],"core":["Theory of Knowledge (TOK)","Extended Essay (EE)","Creativity, Activity, Service (CAS)"]},"British":{"label":"UK / British (IGCSE + A-Level)","structure":"subject-combination","note":"Students typically pick 3 (sometimes 4) A-Level subjects with no formal 'stream' label, but combinations cluster around career direction. Use the combination clusters below to infer course-interest leaning; don't hard-exclude anything since mixed combinations (e.g. Maths + Biology + Art) are common.","subject_pool":{"sciences":["Biology","Chemistry","Physics"],"mathematics":["Mathematics","Further Mathematics"],"humanities":["History","English Literature","Classics","Religious Studies","Geography","Politics","Sociology"],"arts":["Art and Design","History of Art","Design and Technology","Drama/Theatre","Music"],"business_economics":["Economics","Business Studies","Accounting"],"languages":["French","Spanish","Arabic","other Modern Languages"],"computing":["Computer Science"]},"combination_clusters":[{"id":"engineering","subjects":["Mathematics","Physics","Further Mathematics or Chemistry or Computer Science"],"typical_course_interest":["Engineering","Technology / Computer Science"]},{"id":"medicine","subjects":["Biology","Chemistry","Mathematics or Physics"],"typical_course_interest":["Medicine","Dentistry","Life Sciences"]},{"id":"business","subjects":["Mathematics","Economics","Business Studies or Accounting"],"typical_course_interest":["Business / Management","Finance / Accounting","Economics"]},{"id":"law","subjects":["English Literature","History","Politics or Economics"],"typical_course_interest":["Law","Social Sciences"]},{"id":"arts_humanities","subjects":["English Literature","History","Classics or Art and Design"],"typical_course_interest":["Design / Fine Arts","Media / Journalism / Communication","Social Sciences"]}]},"American":{"label":"American (US high school diploma, incl. AP)","structure":"subject-area electives (AP is the advanced signal)","note":"US diploma has broad required core (English, Maths, Science, Social Studies, PE) plus electives; AP course choice is the best signal of academic direction. No hard exclusions.","ap_categories":[{"id":"capstone","label":"AP Capstone","courses":["AP Seminar","AP Research"]},{"id":"arts","label":"Arts","courses":["AP Art History","AP Art & Design","AP Music Theory"],"typical_course_interest":["Design / Fine Arts","Media / Journalism / Communication"]},{"id":"english","label":"English","courses":["AP English Language & Composition","AP English Literature & Composition"]},{"id":"history_social_science","label":"History & Social Sciences","courses":["AP Comparative Government & Politics","AP European History","AP Human Geography","AP Macroeconomics","AP Microeconomics","AP Psychology","AP US Government & Politics","AP US History","AP World History: Modern","AP African American Studies"],"typical_course_interest":["Law","Social Sciences","Psychology","Economics","Business / Management"]},{"id":"math_cs","label":"Math & Computer Science","courses":["AP Calculus AB","AP Calculus BC","AP Precalculus","AP Computer Science A","AP Computer Science Principles","AP Statistics"],"typical_course_interest":["Engineering","Technology / Computer Science","Data Science / Analytics"]},{"id":"sciences","label":"Sciences","courses":["AP Biology","AP Chemistry","AP Environmental Science","AP Physics 1","AP Physics 2","AP Physics C"],"typical_course_interest":["Medicine","Engineering","Life Sciences","Environmental Science"]},{"id":"world_languages","label":"World Languages & Culture","courses":["AP Chinese","AP French","AP German","AP Italian","AP Japanese","AP Latin","AP Spanish Language","AP Spanish Literature"]}]},"UAE MoE":{"label":"UAE Ministry of Education (public / national curriculum)","structure":"stream-based (post-2023 reform)","note":"As of the current MoE reform, Grades 9-12 use four streams rather than the old 'scientific vs literary' split. All students share a compulsory core; streams mainly change the depth of Maths/Science and add electives.","compulsory_core":["Arabic","English","Mathematics","Islamic Education","Social Studies & Moral Education","Physical & Health Education"],"streams":[{"id":"general","label":"General Stream","note":"Default path from Grade 1; can continue after Grade 9.","typical_course_interest":[]},{"id":"advanced","label":"Advanced Stream","note":"Available after Grade 9 for high performers; deeper Maths & Science instruction.","typical_course_interest":["Engineering","Technology / Computer Science","Medicine"]},{"id":"professional","label":"Professional / Vocational Stream","note":"Available after Grade 8; practical, applied curriculum.","typical_course_interest":["Applied / Vocational / Technical programs"]},{"id":"elite","label":"Elite Stream (Advanced Science Program)","note":"For academically outstanding students from Grade 6; heavy Maths/Science emphasis.","typical_course_interest":["Engineering","Medicine","Pure Sciences"]}],"science_subjects_by_stream":["Physics","Chemistry","Biology"],"elective_areas":["Artificial Intelligence & Technology","Arts","Health Sciences","third language (school-dependent)"]},"SABIS":{"label":"SABIS Educational System (network curriculum, exam-aligned)","structure":"exam-track-aligned, not stream-labelled","note":"SABIS is its own K-12 system used across many private schools regardless of nationality; it prepares students toward whichever external exams the school offers (IGCSE/A-Level and/or SAT/AP), so treat a SABIS visitor like the British or American model depending on which external track their specific school follows - ask if unsure.","core_subjects":["English","Mathematics","World Languages","Science","Social Studies","Computer Science","Art","Music","Health","Physical Education"],"external_exam_tracks":["British IGCSE / A-Level","US SAT / AP","TOEFL / IELTS"]},"Other":{"label":"Other national curricula present in small numbers (French, German, Iranian, Pakistani, Philippine, Canadian, Bangladeshi, Spanish, Italian, Japanese, Russian, Australian)","structure":"not individually researched - low volume in this dataset","note":"Each of these has fewer than 10 schools across the three emirates. Rather than building a full subject model for each, the app should fall back to a generic 'What subjects are you currently studying / most interested in?' free-choice question (multi-select across a broad subject list) for visitors from these curricula, and let staff follow up in person. Revisit only if on-the-day volume from one of these curricula turns out to be significant.","school_counts":{"SABIS":10,"Philippine":9,"Pakistani":8,"Iranian":6,"Australian":6,"French":5,"Canadian":4,"German":3,"Japanese":2,"Russian":2,"Bangladeshi":1,"Spanish":1,"Italian":1}}},"app_integration_notes":["Registration flow: after school-name autocomplete selects a school, auto-fill curriculum from schools.json (curriculum_tags[0]); if a school has 2 tags (e.g. dual American/IB schools), ask the visitor to confirm which track they're on.","Once curriculum is known, show the matching stream/subject picker above instead of a generic subject list - this directly implements the stakeholder's 'PCMB excludes Commerce' filtering request for Indian/CBSE, and gives an equivalent filter for British/American/IB/UAE MoE.","Use each stream/cluster's typical_course_interest array to pre-suggest (not force) course-interest options later in the flow, saving the visitor clicks.","For curricula in the 'Other' bucket, skip stream filtering entirely and use the generic subject multi-select."]};
export const DESTINATION_EXAMS = {"schema":"pedagogy.destination-exams.v1","purpose":"Maps each of the app's 10 destination-country options to the competitive/entrance exams relevant to studying there, so the 'Are you preparing for any competitive exam?' question can show only exams relevant to the country/countries the visitor already picked in the destinations step, instead of one long undifferentiated list.","researched":"2026-09-19","country_list_note":"This is the same 10-option destination list already used in the app (9 named countries + Other), matching the stakeholder's 'top 10 countries' request.","destinations":{"India":{"exams":[{"name":"JEE Main","for":"Engineering (NITs, most engineering colleges)"},{"name":"JEE Advanced","for":"Engineering (IITs) — requires qualifying JEE Main first"},{"name":"NEET-UG","for":"Medicine, dentistry, AYUSH courses"},{"name":"CLAT","for":"Law (National Law Universities)"},{"name":"CUET (UG)","for":"Central universities and many state/private universities, all streams"},{"name":"State CET (e.g. KCET, MHT-CET, WBJEE, COMEDK)","for":"State engineering/professional colleges — ask which state"},{"name":"BITSAT","for":"BITS Pilani campuses"},{"name":"VITEEE","for":"VIT campuses"}],"note":"This is Pedagogy's core counselling territory (NEET/JEE/CET already named in the business context) — this list should be treated as the most important one to get right and to keep current each cycle."},"United Arab Emirates":{"exams":[{"name":"EmSAT","for":"Mandatory placement/admission test (Math, Physics, Chemistry, Biology, Arabic, English) for UAE federal universities (e.g. UAEU, HCT) and many private universities — required regardless of A-Level/IB/CBSE results"},{"name":"SAT","for":"Optional but strengthens applications and scholarship eligibility, especially for American-curriculum-track private universities"}],"note":"English proficiency (IELTS/TOEFL) is commonly also requested but is a language test, not a competitive/subject exam — keep it out of this list unless the app later adds a separate language-requirements question."},"United Kingdom":{"exams":[{"name":"UCAT","for":"Medicine and dentistry (BMAT was discontinued after the 2024 admissions cycle — UCAT is now the standard test)"},{"name":"LNAT","for":"Law at several top law schools"},{"name":"TMUA","for":"Mathematics and some Computer Science courses at a number of universities"},{"name":"ESAT","for":"Engineering/Natural Sciences/Computer Science at a small group of universities (e.g. Cambridge, Imperial) — replaced the older ENGAA/NSAA tests from 2024 entry"}],"note":"Most UK applicants don't sit any admissions test at all — these apply only to specific competitive courses/universities. Verify against the specific university before finalizing question copy."},"Germany":{"exams":[{"name":"TestAS","for":"Mandatory for non-EU/EEA applicants to bachelor's degrees at many German public universities; optional but useful as a tiebreaker for EU applicants to competitive Numerus-Clausus programs (medicine, dentistry, psychology, top Computer Science)"},{"name":"APS Certificate","for":"Not an exam — a mandatory academic-credentials verification process/interview required for Indian (and Chinese, Vietnamese) students before a German student visa can be issued. Commonly asked about in the same breath as TestAS, so keep it listed here even though it isn't a test to 'prepare for' in the usual sense."},{"name":"TestDaF / DSH","for":"German-language proficiency — only relevant if the chosen program is taught in German rather than English"}]},"Singapore":{"exams":[{"name":"SAT","for":"Used by NUS, NTU and SMU to evaluate applicants presenting non-Singaporean qualifications (e.g. Indian CBSE/ISC/CISCE boards) — the standard extra requirement for Indian applicants"}],"note":"There is no separate Singapore-national entrance exam for foreign applicants — admission is mainly on board results (A-Level/IB/CBSE/etc.) plus SAT."},"Ireland":{"exams":[{"name":"HPAT-Ireland","for":"Medicine and some health-profession programmes at 6 Irish universities (Trinity, UCD, UCC, Galway, Limerick, RCSI) — note: international/non-EU applicants are often exempt depending on the university and programme, so this needs a follow-up question or counsellor check rather than being assumed"}],"note":"CAO (the points-based admissions system) applies to Irish/EU Leaving Certificate students, not to international applicants presenting other qualifications, so it isn't listed here as an 'exam.'"},"Canada":{"exams":[{"name":"SAT / ACT","for":"Optional at most Canadian universities but strengthens applications and scholarship chances"},{"name":"MCAT","for":"Medicine (graduate-entry)"},{"name":"LSAT","for":"Law"},{"name":"GRE / GMAT","for":"Graduate programmes and MBA"}],"note":"English-proficiency tests (IELTS/TOEFL/PTE/CELPIP/CAEL) are also commonly required but are language tests, not competitive/subject exams — kept out of this list for the same reason as UAE."},"Australia":{"exams":[{"name":"UCAT ANZ","for":"Medicine and dentistry — mandatory for most direct-entry undergraduate medical programmes"},{"name":"ISAT","for":"An alternate pathway test used by some medicine/health-science programmes"},{"name":"GAMSAT","for":"Graduate-entry medicine and veterinary science"},{"name":"SAT / ACT","for":"Optional for general undergraduate admission"},{"name":"GRE / GMAT","for":"Graduate programmes and MBA"}]},"United States":{"exams":[{"name":"SAT / ACT","for":"Undergraduate admission (many US universities are now test-optional — still worth asking, since a strong score still helps scholarships)"},{"name":"GRE","for":"Most graduate (Master's/PhD) programmes"},{"name":"GMAT","for":"MBA and business Master's programmes"},{"name":"MCAT","for":"Medical school"},{"name":"LSAT","for":"Law school"}]},"Other":{"exams":[],"note":"No fixed list — when 'Other' is the only or an additional destination, show a free-text 'Which exam(s)?' field instead of a chip list, and flag the record for a counsellor to follow up rather than guessing at a country-specific list."}},"app_integration_notes":["New question, gated by a simple Yes/No: 'Are you preparing for any competitive exam?' Show it after the destination-country selection (Path Swipe deck / grid step) is answered, since it depends on that answer.","If Yes: build the exam chip list dynamically from this file, keyed off whichever countries the visitor selected in the destinations step. If they selected more than one country, union the exam lists (dedupe exact name matches like 'SAT / ACT' or 'GRE / GMAT' that appear under multiple countries) and group them under their country/subheading so it's clear which exam applies where, rather than one flattened list.","If No: skip straight past this question, same as any other optional preference step — don't force an answer.","If 'Other' is the only destination chosen (or included alongside named countries with no exam data), fall back to a free-text field per the 'Other' entry's note above.","This reuses the same interaction pattern as the destinations step itself (tap chips, not swipe) — see the structural-reference note in CLAUDE.md / session_handoff.md about using reference/pedagogy-expo.html's chip-based preferences(2) step (which already had a flat, non-country-aware 'exams' chip list) as the starting point, now made country-aware using this file."]};
export const QUESTION_BANK = {"schema":"pedagogy.question-bank.v1","purpose":"Academic quiz question bank for the Sharjah Expo app. STUB DATA ONLY — Abhi has not yet delivered the real bank (target ~50-70 questions per subject per difficulty tier per curriculum, per CLAUDE.md/session_handoff.md Section 3K). This file exists so the loader, validator and eligibility-filtering logic can be built and tested now; every question below is a placeholder, not reviewed content.","note_on_stream_ids":"eligible_stream_ids values must match an 'id' inside data/curriculum_subjects.json's curricula[curriculum].streams[].id (stream-based curricula, e.g. Indian's 'science-pcmb') or .groups[].id (group-based curricula, e.g. IB's 'group4'). An empty array means the question applies to every stream/group within that curriculum. Curricula with no stream/group structure (the curriculum_subjects.json 'Other' bucket) should always use an empty array here.","questions":[{"id":"stub-indian-physics-medium-001","curriculum":"Indian","eligible_stream_ids":["science-pcm","science-pcb","science-pcmb"],"subject":"Physics","difficulty":"medium","topic":"Motion","language":"en","q":"A cyclist travels 24 metres in 4 seconds at constant speed. What is the speed?","options":["4 m/s","6 m/s","12 m/s","24 m/s"],"answer":"6 m/s","explanation":"Speed = distance / time = 24 / 4 = 6 m/s.","reviewed_by":null},{"id":"stub-indian-business-medium-001","curriculum":"Indian","eligible_stream_ids":["commerce-with-maths","commerce-without-maths"],"subject":"Business Studies","difficulty":"medium","topic":"Profit","language":"en","q":"A product costs AED 60 and sells for AED 80. Ignoring other costs, profit per unit is:","options":["AED 10","AED 20","AED 40","AED 60"],"answer":"AED 20","explanation":"Selling price minus unit cost: 80 - 60 = 20.","reviewed_by":null},{"id":"stub-ib-sciences-easy-001","curriculum":"IB","eligible_stream_ids":["group4"],"subject":"Biology","difficulty":"easy","topic":"Cells","language":"en","q":"Which structure controls movement of substances into and out of a cell?","options":["Cell membrane","Nucleus","Ribosome","Chromosome"],"answer":"Cell membrane","explanation":"The membrane selectively controls exchange with the cell's environment.","reviewed_by":null},{"id":"stub-other-reasoning-easy-001","curriculum":"Other","eligible_stream_ids":[],"subject":"Reasoning","difficulty":"easy","topic":"Patterns","language":"en","q":"Continue the same pattern: 4, 8, 12, ...","options":["14","16","18","20"],"answer":"16","explanation":"Add four each time.","reviewed_by":null}]};
